const active=(cards,dots,n)=>{cards.forEach((c,i)=>c.classList.toggle('is-current',i===n));dots.forEach((d,i)=>d.classList.toggle('is-active',i===n))};
const motion=s=>{const track=s.querySelector('.story-showcase-v1-track'),cards=[...s.querySelectorAll('.story-showcase-v1-card')],dots=[...s.querySelectorAll('.story-showcase-v1-dots i')],imgs=cards.map(c=>c.querySelector('img')),acts=[...s.querySelectorAll('.story-showcase-v1-actions')];if(!track||cards.length<2)return;s.classList.add('story-st2');cards.forEach(c=>c.classList.add('is-visible'));active(cards,dots,0);const mobile=()=>matchMedia('(max-width:760px)').matches,travel=()=>Math.max(0,track.scrollWidth-s.clientWidth);gsap.set(track,{x:0,y:mobile()?'20vh':'14vh'});gsap.set(cards,{scale:mobile()?.86:.9,opacity:.38,transformOrigin:'50% 50%'});gsap.set(cards[0],{opacity:.98});gsap.set(imgs,{scale:1.1,yPercent:4});gsap.set(acts,{opacity:0,y:22});const tl=gsap.timeline({defaults:{ease:'none'},scrollTrigger:{trigger:s,start:'top top',end:()=>`+=${Math.round(innerHeight*(mobile()?2.35:2.05))}`,pin:true,pinSpacing:true,scrub:.72,anticipatePin:1,invalidateOnRefresh:true,onUpdate:self=>active(cards,dots,self.progress<.56?0:1)}});tl.to(track,{y:0,duration:.18},0).to(cards,{scale:1,opacity:1,duration:.18,stagger:.018},0).to(acts,{opacity:1,y:0,duration:.12,stagger:.02},.08).to(imgs,{scale:1.035,yPercent:0,duration:.22,stagger:.015},0).to(track,{x:()=>-travel(),duration:.62},.18).to(cards[0],{scale:mobile()?.92:.95,opacity:.7,duration:.34},.38).fromTo(cards[1],{scale:mobile()?.93:.96,opacity:.78},{scale:1,opacity:1,duration:.34,immediateRender:false},.4).to(imgs[0],{xPercent:-3.5,duration:.42},.28).fromTo(imgs[1],{xPercent:3.5},{xPercent:0,duration:.42,immediateRender:false},.4).to(track,{y:mobile()?'-3.5vh':'-2.5vh',duration:.14},.84).to(s.querySelector('.story-showcase-v1-dots'),{opacity:.45,duration:.1},.88);const refresh=()=>ScrollTrigger.refresh();imgs.forEach(i=>{if(!i.complete){i.addEventListener('load',refresh,{once:true});i.addEventListener('error',refresh,{once:true})}});const ro='ResizeObserver'in window?new ResizeObserver(refresh):null;ro?.observe(s);requestAnimationFrame(refresh);addEventListener('pagehide',()=>{ro?.disconnect();tl.scrollTrigger?.kill();tl.kill()},{once:true})};
const init=async()=>{addCss();document.querySelectorAll('.story-showcase:not(.story-showcase-v1)').forEach(n=>n.remove());const s=await waitSection();if(!s)return;artwork(s);s.classList.add('story-st2');if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;try{await libs();motion(s)}catch(e){console.warn('[stories] ScrollTrigger fallback',e)}};
